files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --radius: 4px;
  --shadow: 4px 4px 0 #0a0a15;
  --font: 'Courier New', Courier, monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle, #2a2a4a 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 420px;
}

h1 {
  text-align: center;
  font-size: 2rem;
  letter-spacing: 2px;
  margin: 0 0 20px;
  color: var(--primary);
  text-shadow: 3px 3px 0 #0a0a15;
}

.card {
  background: var(--card);
  border: 3px solid var(--primary);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: none;
  padding: 0;
  margin: 0;
}

label, legend {
  font-size: 1rem;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  font-family: var(--font);
  font-size: 1.2rem;
  padding: 12px;
  background: var(--bg);
  border: 3px solid var(--accent);
  border-radius: var(--radius);
  color: var(--text);
  width: 100%;
}

input[type="number"]:focus {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
  border-color: var(--primary);
}

input[type="number"]:hover {
  border-color: var(--primary);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  font-family: var(--font);
  font-size: 1.1rem;
  padding: 12px 8px;
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--accent);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
}

.tip-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.tip-btn[aria-pressed="true"] {
  background: var(--primary);
  border-color: var(--primary);
  box-shadow: inset 0 0 0 3px var(--card);
}

.tip-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.results {
  border-top: 3px dashed var(--accent);
  padding-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.result-value {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--primary);
  text-shadow: 2px 2px 0 #0a0a15;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

@media (max-width: 400px) {
  body { font-size: 16px; padding: 8px; }
  h1 { font-size: 1.6rem; }
  .card { padding: 16px; }
  .tip-buttons { flex-direction: column; }
  .tip-btn { width: 100%; }
  .result-value { font-size: 1.3rem; }
}

document.addEventListener('DOMContentLoaded', () => {
  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tip-per-person');
  const totalPerPersonEl = document.getElementById('total-per-person');

  let selectedTip = 0;

  function calculate() {
    const bill = parseFloat(billInput.value) || 0;
    const people = parseInt(peopleInput.value, 10) || 1;
    const safePeople = Math.max(1, people);
    const tipAmount = bill * (selectedTip / 100);
    const total = bill + tipAmount;
    const tipPerPerson = tipAmount / safePeople;
    const totalPerPerson = total / safePeople;

    tipPerPersonEl.textContent = '$' + tipPerPerson.toFixed(2);
    totalPerPersonEl.textContent = '$' + totalPerPerson.toFixed(2);
  }

  function selectTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(btn => {
      const isActive = parseInt(btn.dataset.tip, 10) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const percent = parseInt(btn.dataset.tip, 10);
      selectTip(percent);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize with 15% selected
  selectTip(15);
});
